"use strict";
// temp.civet

type AutoPromise<T> = Promise<Awaited<T>>;
import {range} from 'base'
import {hash, hashof} from 'datatypes'
import {EXEC} from 'llutils'
import {procFiles} from 'proc-files'
import {doCompileCivet} from 'civet'

// ---------------------------------------------------------------------------

const avg = (lNumbers: number[]): number => {

	let sum = 0
	for (const i of lNumbers) {
		sum += i
	}
	return sum / lNumbers.length
}

// ---------------------------------------------------------------------------

await EXEC(async () => {
	const pat = '**/*.lib.civet'
	const hOptions: hash = {force: true}

	const hData: hashof<number[]> = {}

	const test = async (n: number): AutoPromise<void> => {
		hOptions.maxRunning = (n > 0) ? n : Infinity
		const [hCounts, timeTaken] = await procFiles([doCompileCivet, pat], hOptions)
		if (hCounts.err > 0) {
			console.log("There were errors")
			Deno.exit(-1)
		}
		const nStr = n.toString()
		if (!(nStr in hData)) {
			hData[nStr] = [] as number[]
		}
		hData[nStr].push(timeTaken)
	}

	for (const rep of range(5)) {
		for (const i of range(10)) {
			await test(i)
		}
	}

	console.log(hData)

	for (const key in hData) {const lItems = hData[key];
		console.log(`[${key}] ${avg(lItems)}`)
	}
})


